import numpy as np

def calculate_stats_for_students(test_results):
    """
    Calculate the average test score and the standard deviation for each student.

    Parameters:
    test_results (list of dict): Each dictionary contains test results for
        students. Two shapes are supported:
          * one record per test: {'student_id': 1, 'score': 85}
          * one record per student: {'student_id': 1, 'scores': [85, 90, 78]}
        The student identifier key may be any key containing 'student' or 'id'
        (e.g. 'student_id', 'Student', 'id'); the score key may be any key
        containing 'score', 'test' or 'grade' (e.g. 'score', 'scores',
        'test_scores').

    Returns:
    dict: keys are student IDs, values are tuples (average score, standard
          deviation) as floats.

    Raises:
    ValueError: if a student present in the input does not have any test scores.
    """
    if test_results is None:
        test_results = []

    collected = {}

    for entry in test_results:
        if not isinstance(entry, dict):
            raise ValueError("Each test result must be a dictionary")

        sid = None
        score_values = []

        for key, value in entry.items():
            key_l = str(key).lower()
            if 'student' in key_l or key_l == 'id':
                sid = value
            elif 'score' in key_l or 'test' in key_l or 'grade' in key_l:
                if value is None:
                    continue
                if isinstance(value, (list, tuple, set, np.ndarray, pd.Series)):
                    score_values.extend(list(value))
                else:
                    score_values.append(value)

        if sid is None:
            raise ValueError("Could not determine the student ID for a test result entry")

        bucket = collected.setdefault(sid, [])
        for v in score_values:
            if v is None:
                continue
            if isinstance(v, float) and np.isnan(v):
                continue
            bucket.append(v)

    results = {}
    for sid, scores in collected.items():
        if len(scores) == 0:
            raise ValueError(f"Student {sid} does not have any test scores")
        arr = np.asarray(scores, dtype=float)
        results[sid] = (float(np.mean(arr)), float(np.std(arr)))

    return results


